#!/usr/bin/env python3
# FLOWPACK - FASE 6: BOTOES MAIS/MENOS SO COM CARTAO NFC (painel)
# Uso:  python3 /root/instalar_fase6.py      (rode DEPOIS do instalar_fase5.py)
# Legenda:  ✅ aplicado   ⏭️  ja estava aplicado   ❌ nao deu (me mande a linha)
import os, sys, shutil, subprocess, datetime, base64
BASE = sys.argv[1] if len(sys.argv) > 1 else "/root/site_esteira"
SERVER = os.path.join(BASE, "server.js"); VIEWS = os.path.join(BASE, "views")
BLOCO = base64.b64decode("").decode("utf-8"); PAGINA = base64.b64decode("").decode("utf-8")
if not os.path.exists(SERVER): print("❌ Nao achei " + SERVER); sys.exit(1)
c = open(SERVER, encoding="utf-8").read()
if "CARTOES NFC: so cartao de DONO" not in c: print("❌ A fase 5 (cartao NFC) ainda nao esta instalada. Rode primeiro o instalar_fase5.py."); sys.exit(1)
carimbo = datetime.datetime.now().strftime("%Y%m%d_%H%M%S"); shutil.copy2(SERVER, SERVER + ".bak_" + carimbo)
print("Copia de seguranca criada (.bak_" + carimbo + ")\n"); res = []
destino = os.path.join(VIEWS, "nfc.html")
if os.path.exists(destino) and open(destino, encoding="utf-8").read() == PAGINA: res.append("⏭️  Pagina Cartoes NFC: ja estava atualizada.")
else:
    if os.path.exists(destino): shutil.copy2(destino, destino + ".bak_" + carimbo)
    open(destino, "w", encoding="utf-8").write(PAGINA); res.append("✅ Pagina Cartoes NFC: atualizada (mostra os botoes liberados/bloqueados).")
def unico(t, a):
    if t.count(a) != 1: raise Exception("trecho nao encontrado (%d vezes)" % t.count(a))
def aplicar(nome, marcador, fn):
    global c
    if marcador in c: res.append("⏭️  %s: ja estava aplicado." % nome); return
    try: novo = fn(c)
    except Exception as e: res.append("❌ %s: %s" % (nome, e)); return
    c = novo; res.append("✅ %s: aplicado." % nome)
def f_bloco(t):
    a = "setInterval(() => { if (nfcOnline && Date.now() - nfcUltimaMsg > 15000) nfcOnline = false; }, 3000);"; unico(t, a); return t.replace(a, a + "\n" + BLOCO, 1)
def f_janela(t):
    a = "    nfcFalhas = [];\n    if (emergenciaGlobal.ativa) { emergenciaLiberar('cartao NFC de '"; unico(t, a); return t.replace(a, "    nfcFalhas = [];\n    nfcJanelaAte = agora + NFC_JANELA_MS;\n    if (emergenciaGlobal.ativa) { emergenciaLiberar('cartao NFC de '", 1)
def f_receita(t):
    a = "    if (emergenciaGlobal.ativa) return;\n    if (!receitas.botoesAtivos) return;"; unico(t, a); return t.replace(a, "    if (emergenciaGlobal.ativa) return;\n    if (!nfcJanelaAberta()) return;\n    if (!receitas.botoesAtivos) return;", 1)
def f_sub(t):
    a = "mqttClient.subscribe(['nfc/leitura', 'nfc/status']);"; unico(t, a); return t.replace(a, "mqttClient.subscribe(['nfc/leitura', 'nfc/status', 'painel/botao']);", 1)
def f_msg(t):
    a = "if (topic.startsWith('nfc/')) nfcTratarMqtt(topic, valor);"; unico(t, a); return t.replace(a, a + "\n    if (topic === 'painel/botao') painelTratarBotao(valor);", 1)
def f_api(t):
    a = "bloqueadoS: Math.max(0, Math.ceil((nfcBloqueadoAte - Date.now()) / 1000)),"; unico(t, a); return t.replace(a, a + "\n        janelaS: Math.max(0, Math.ceil((nfcJanelaAte - Date.now()) / 1000)),", 1)
aplicar("Servidor: painel e janela de controle (MAIS/MENOS so com cartao)", "function painelTratarBotao", f_bloco)
aplicar("Servidor: cartao aceito abre a janela", "nfcJanelaAte = agora + NFC_JANELA_MS;", f_janela)
aplicar("Servidor: MAIS/MENOS (inclusive os da esteira) exigem a janela", "if (!nfcJanelaAberta()) return;", f_receita)
aplicar("Servidor: inscricao dos botoes do painel", "'painel/botao']);", f_sub)
aplicar("Servidor: tratamento dos botoes do painel", "painelTratarBotao(valor);", f_msg)
aplicar("Servidor: tela mostra o tempo restante", "janelaS: Math.max(0", f_api)
open(SERVER, "w", encoding="utf-8").write(c)
print("\n".join(res)); print()
ok = subprocess.run(["node", "-c", SERVER], capture_output=True, text=True)
if ok.returncode == 0: print("✅ server.js sem erro de sintaxe.")
else: print("❌ ERRO DE SINTAXE:"); print(ok.stderr); print("Para voltar:  cp " + SERVER + ".bak_" + carimbo + " " + SERVER); sys.exit(1)
print("⚠️  Teve ❌ acima. Me mande essas linhas." if any(l.startswith("❌") for l in res) else "\nTudo certo! Reinicie:  sudo systemctl restart site_esteira   (depois Ctrl+Shift+R)")
